def cc(n):
    s = ''
    while n != 0:
        s = str(n % 4) +  s
        n //= 4
    return s

def f(n):
    s = cc(n)
    sum_digits = sum(map(int,list(s)))
    if sum_digits % 3 == 0:
        s = s.replace('0','*').replace('2','0').replace('*','2')
        s = '32' + s
    else:
        s += '33'
        s = s[0] + '10' + s[3:]
    return int(s,4)

